            <YAxis
              allowDecimals={false}
              tick={{ fontSize: 11, fill: "#64748b" }}
              label={{
                value: "Top-1 seats",
                angle: -90,
                position: "insideLeft",
                style: { fontSize: 11, fill: "#64748b" },
              }}
            />
            <Tooltip itemSorter={sortTooltipPayload} />
            <Bar dataKey="mineTop1Count" name="Mine Top-1" stackId="a" fill="#f59e0b" />
            <Bar
              dataKey="midTop1Count"
              name="Midstream Top-1"
              stackId="a"
              fill="#f43f5e"
              radius={[4, 4, 0, 0]}
            />
          </BarChart>
        </ResponsiveContainer>
      </div>
    );
  }

  const rows = REGION_TOP1_SEATS.filter(
    (r) => r.mineTop1Seats + r.midTop1Seats > 0,
