  YAxis,
  ZAxis,
} from "recharts";
import { Tooltip } from "@/components/charts/SortedTooltip";
import {
  ALL_GEOGRAPHIES,
  COUNTRY_HUBS,
  GEO_SCATTER,
  HEADLINE,
  MIDSTREAM_GEOGRAPHIES,
  MINE_GEOGRAPHIES,
  REGION_TOP1_SEATS,
  SOURCE_NOTE,
  STAGE_FLIPS,
  fmtPct,
  getCommodityById,
  regionShares,
  type CommodityGeo,
  type Stage,
} from "@/data/chokepoint-commodities-geography-2026-data";

// viz-types: country share bars, regional pie, mine???mid flip dumbbell, mine??mid scatter, regional Top-1 seats | layout: default

type ViewId = "shares" | "flips" | "scatter" | "hubs";
type StageFilter = "all" | Stage;

function ChartCard({
  title,
  subtitle,
  children,
}: {
  title: string;
  subtitle?: string;
  children: React.ReactNode;
}) {
