"use client";

import { useMemo, useState } from "react";
import {
  Bar,
  BarChart,
  CartesianGrid,
  Cell,
  Pie,
  PieChart,
  ResponsiveContainer,
  Scatter,
  ScatterChart,
  XAxis,
  YAxis,
  ZAxis,
} from "recharts";
import { Tooltip } from "@/components/charts/SortedTooltip";
import {
  ALL_GEOGRAPHIES,
  COUNTRY_HUBS,
  GEO_SCATTER,
  HEADLINE,
  MIDSTREAM_GEOGRAPHIES,
  MINE_GEOGRAPHIES,
  REGION_TOP1_SEATS,
  SOURCE_NOTE,
  STAGE_FLIPS,
  fmtPct,
  getCommodityById,
  regionShares,
  type CommodityGeo,
  type Stage,
} from "@/data/chokepoint-commodities-geography-2026-data";

// viz-types: country share bars, regional pie, mine???mid flip dumbbell, mine??mid scatter, regional Top-1 seats | layout: default

type ViewId = "shares" | "flips" | "scatter" | "hubs";
type StageFilter = "all" | Stage;

function ChartCard({
  title,
  subtitle,
  children,
}: {
  title: string;
  subtitle?: string;
  children: React.ReactNode;
}) {
  return (
    <div className="w-full min-w-0 overflow-hidden rounded-xl border border-slate-200 bg-white shadow-sm">
      <div className="border-b border-slate-100 bg-slate-50 px-5 py-4">
        <h3 className="text-lg font-bold text-slate-900">{title}</h3>
        {subtitle && <p className="mt-1 text-sm text-slate-500">{subtitle}</p>}
      </div>
      <div className="p-4 sm:p-6">{children}</div>
    </div>
  );
}

function ToggleGroup<T extends string>({
  label,
  value,
  options,
  onChange,
}: {
  label: string;
  value: T;
  options: { id: T; label: string }[];
  onChange: (v: T) => void;
}) {
  return (
    <div className="flex flex-wrap items-center gap-2">
      <span className="text-xs font-semibold uppercase tracking-wide text-slate-500">
        {label}
      </span>
      <div className="inline-flex flex-wrap rounded-lg border border-slate-200 bg-white p-0.5">
        {options.map((o) => (
          <button
            key={o.id}
            type="button"
            onClick={() => onChange(o.id)}
            className={`rounded-md px-3 py-1.5 text-xs font-semibold transition ${
              value === o.id
                ? "bg-slate-900 text-white"
                : "text-slate-600 hover:bg-slate-50"
            }`}
          >
            {o.label}
          </button>
        ))}
      </div>
    </div>
  );
}

function CountrySharePanel({ geo }: { geo: CommodityGeo }) {
  const rows = useMemo(
    () =>
      [...geo.countries]
        .filter((c) => c.iso !== "XX")
        .sort((a, b) => b.sharePct - a.sharePct),
    [geo],
  );

  return (
    <div className="h-[340px] w-full min-w-0">
      <ResponsiveContainer width="100%" height="100%">
        <BarChart
          data={rows}
          layout="vertical"
          margin={{ top: 8, right: 24, left: 8, bottom: 8 }}
        >
          <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" horizontal={false} />
          <XAxis
            type="number"
            domain={[0, "dataMax"]}
            tickFormatter={(v) => `${v}%`}
            tick={{ fontSize: 11, fill: "#64748b" }}
          />
          <YAxis
            type="category"
            dataKey="country"
            width={120}
            tick={{ fontSize: 11, fill: "#334155" }}
          />
          <Tooltip
            formatter={(value) => [fmtPct(Number(value), 1), "Share"]}
            labelFormatter={(l) => String(l)}
          />
          <Bar dataKey="sharePct" radius={[0, 4, 4, 0]} maxBarSize={28}>
            {rows.map((r) => (
              <Cell key={r.iso} fill={r.fill} />
