          </Bar>
        </BarChart>
      </ResponsiveContainer>
    </div>
  );
}

function RegionalPiePanel({ geo }: { geo: CommodityGeo }) {
  const rows = useMemo(() => regionShares(geo), [geo]);

  return (
    <div className="h-[340px] w-full min-w-0">
      <ResponsiveContainer width="100%" height="100%">
        <PieChart>
          <Pie
            data={rows}
            dataKey="sharePct"
            nameKey="region"
            cx="50%"
            cy="50%"
            innerRadius={58}
            outerRadius={110}
            paddingAngle={2}
          >
            {rows.map((r) => (
              <Cell key={r.region} fill={r.fill} />
